import { promises as fs } from 'node:fs';
import { httpError } from '@strafor/node-common';
import type { PayrollAdapter } from './types.js';

/**
 * bank_dispersion — export-only adapter. It produces no provider results of
 * its own; the CLABE-interbancaria dispersion file is generated by
 * POST /v1/payroll/periods/:id/dispersion. This adapter exists so the
 * provider row carries validated config:
 *
 * Config:
 *   rfc:      empresa RFC for the dispersion header (required, 12-13 chars;
 *             placeholder XAXX010101000 is used by the route when no provider
 *             is configured)
 *   bankName: optional originating-bank label recorded on the export
 */
export function createBankDispersionAdapter(importsDir: string): PayrollAdapter {
    return {
        async fetchPeriodResults() {
            throw httpError(422, 'bank_dispersion is an export-only adapter — it cannot import period results');
        },

        async validateConfig(config) {
            if (typeof config.rfc !== 'string' || !/^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/i.test(config.rfc)) {
                throw httpError(400, "bank_dispersion config.rfc is required (valid RFC format, e.g. 'XAXX010101000')");
            }
            if (config.bankName !== undefined && typeof config.bankName !== 'string') {
                throw httpError(400, 'bank_dispersion config.bankName must be a string');
            }
            try {
                await fs.access(importsDir, fs.constants.R_OK);
            } catch {
                throw httpError(400, `bank_dispersion IMPORTS_DIR '${importsDir}' is not readable`);
            }
        }
    };
}
